/**
 * Appearance model: three independent settings applied as attributes on <html>, which the CSS
 * tokens key off (styles/themes, styles/tokens). public/theme-init.js applies the saved values
 * before first paint; keep its storage key and logic in sync with this file.
 */

import { GENERATED_PALETTES } from './palettes.gen';

export const THEMES = ['system', 'light', 'dark'] as const;
export const DENSITIES = ['comfortable', 'compact'] as const;

/**
 * Every palette, in display order: the hand-tuned ones in styles/themes/themes.css, then the ones
 * generated by `pnpm gen:palettes` (gen/palettes.mts) into palettes.gen.css.
 */
export const PALETTES = [
  { name: 'stone', label: 'Stone' },
  { name: 'signal', label: 'Signal' },
  { name: 'slate', label: 'Slate' },
  ...GENERATED_PALETTES,
] as const;

export type Theme = (typeof THEMES)[number];
export type Palette = (typeof PALETTES)[number]['name'];
export type Density = (typeof DENSITIES)[number];

export interface Appearance {
  theme: Theme;
  palette: Palette;
  density: Density;
}

/** localStorage key of the persisted UI store (stores/ui-store.ts), read by theme-init.js. */
export const UI_STORAGE_KEY = 'app.ui';

export const DEFAULT_APPEARANCE: Appearance = { theme: 'system', palette: 'stone', density: 'comfortable' };

export function resolveTheme(theme: Theme, prefersDark: boolean): 'light' | 'dark' {
  if (theme === 'system') return prefersDark ? 'dark' : 'light';
  return theme;
}

export function applyAppearance(root: HTMLElement, appearance: Appearance, prefersDark: boolean): void {
  // Suppress transitions for this frame so a switch is instant (styles/base/base.css).
  root.setAttribute('data-appearance-switching', '');
  root.dataset['theme'] = resolveTheme(appearance.theme, prefersDark);
  root.dataset['palette'] = appearance.palette;
  root.dataset['density'] = appearance.density;
  requestAnimationFrame(() => root.removeAttribute('data-appearance-switching'));
}
